15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
22	    @Mapping(target = "initials", expression = "java(initials(owner))")
23	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
24	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    OwnerDto toOwnerDto(Owner owner);
27	
28	    /**
29	     * Fixed city-to-region table used to derive an owner's locality.
30	     */
31	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
32	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
33	
34	    /**
35	     * Derives the owner's locality from its city using the fixed city-to-region table
36	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). Returns the canonical region string,
37	     * or {@code 'UNKNOWN'} when the city is not in the table.
38	     */
39	    default String locality(Owner owner) {
40	        if (owner == null) {
41	            return null;
42	        }
43	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
44	    }
45	
46	    /**
47	     * Returns the owner's numeric membership level, assigned on creation. The level starts at
48	     * {@code 1}, gains {@code 1} when an email is present, gains {@code 1} when the owner has no
49	     * namesakes (namesakeCount is 0), and is capped at {@code 3} (level 4 is reserved for tenure).
50	     */
51	    default Integer membershipLevel(Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        int level = 1;
56	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
57	        if (hasEmail) {
58	            level++;
59	        }
60	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
61	        if (noNamesakes) {
62	            level++;
63	        }
64	        return Math.min(level, 3);
65	    }
66	
67	    /**
68	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the
69	     * last two digits of the registrationDate year, e.g. {@code 'SMI-0007-M26'}. Returns
70	     * {@code null} when the owner has no customer code or registration date.
71	     */
72	    default String membershipNumber(Owner owner) {
73	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
74	            return null;
75	        }
76	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
77	    }
78	
79	    /**
80	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
81	     */
82	    default String displayName(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        return owner.getLastName() + ", " + owner.getFirstName();
87	    }
88	
89	    /**
90	     * Returns the owner's initials as the upper-cased first letters of firstName and
91	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
92	     */
93	    default String initials(Owner owner) {
94	        if (owner == null) {
95	            return null;
96	        }
97	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
98	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
99	    }
100	
101	    Owner toOwner(OwnerDto ownerDto);
102	
103	    @Mapping(target = "id", ignore = true)
104	    @Mapping(target = "pets", ignore = true)
105	    Owner toOwner(OwnerFieldsDto ownerDto);
106	
107	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
108	
109	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
110	
111	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
112	        OwnerPageDto ownerPageDto = new OwnerPageDto();
113	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
114	        ownerPageDto.setPage(ownerPage.getNumber());
115	        ownerPageDto.setSize(ownerPage.getSize());
116	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
117	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
118	        return ownerPageDto;
119	    }
120	}
